#!/usr/bin/env python3
"""
Round 218o (culprits), 16 October 2026. Needs round 217o.

The Abortion and Rape maps as rows (abortion_grid, rape_registries), and a
panel that shows a registry's own site inside the map.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ['## Round 218o (16 October)\n\nNeeds round 217o (guards on its heading). No tiles patch: the two maps are\nread by the daily site-map build once they are in the maps repo. No app.js?v=\nbump. Its own files in the maps repo: abortion.html and rape.html (top folder).\n\n- Owner, 16 October: a map and layer for each of the On-Planet Invasion\n  page\'s sections (b) Abortion and (i) Rape. The rape one with the world\'s\n  sex-offender registries at every level of government (data where it can be\n  used, links otherwise); then: show each registry inside the map over its\n  region, where the site allows it; and map the whole abortion grid, not only\n  the names in the section.\n- Rows abortion_grid (new heading "Abortion" under Pre-birth frontlines,\n  after Human reproduction and gene therapy) and rape_registries (new h4\n  "Rape" at the end of Invasion of humans, before Of countries by countries).\n  Both route "sitemap", keepColour, registry.json entries without "rich".\n- siteFrameClick: a box element with data-wtyg-frame="https://..." opens the\n  page in a panel over the map (large in the middle, or small in the corner),\n  with open-in-tab and a note. Only https. Rape map registries whose sites\n  loaded in a frame in a headless browser on 16 October carry the button (48);\n  the rest open in a new tab.\n- Owner\'s licence choices (16 October): sources with no stated licence are\n  used with credit; non-commercial licences are fine (the site is\n  non-commercial); sources whose terms forbid copying without written\n  permission are left out until permission is given: Planned Parenthood\'s\n  health-centre and affiliate lists, NAF\'s provider list, New Zealand\'s\n  DECIDE list, UNODC\'s sexual-violence counts, the Gates grants file, and Plan\n  C\'s directory (its terms forbid scraping; the online services were rebuilt\n  from each service\'s own site).\n- No registered person\'s name or address is copied; registry dots sit at the\n  seat of the body that runs the registry.\n- Tests: one block before "round 215r" in map/test.mjs.\n']

DIFF = ""


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round218o: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 217o" not in h.read_text(encoding="utf-8"):
        sys.exit("round218o: round 217o must be applied first (round217o_culprits.py)")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", path, check=False).returncode == 0:
        print("round218o: already applied")
    else:
        r = git("apply", "--3way", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", "pipeline/sitemaps/registry.json", check=False)
            sys.exit("round218o: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round218o: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
